+		publication: {
+			uri: publication.envelope.uri,
+			name: publication.value.name,
+			url: publication.value.url,
+			description: publication.value.description,
+		},
+		posts,
+		source: { repo: config.repo, did: source.did, pds: source.pds },
+	};
