+		statusMessage?: string;
+		message?: string;
+	} | null;
+	if (!response.ok) {
+		throw new BlogApiError(
+			payload?.statusMessage ?? payload?.message ?? "The AT Protocol blog is unavailable.",
+			response.status,
+		);
+	}
+	if (!isBlogFeed(payload)) {
